// Expo config plugin: signs release builds with our own keystore instead of debug.keystore (A1).
// android/ is generated by `expo prebuild`, so the signing config has to be injected here.
// The keystore path and passwords come from ~/.gradle/gradle.properties (PM_RELEASE_*), never
// from the repo. If they are missing, `validateSigningRelease` fails the release build: it must
// never fall back to the public debug key.
const { withAppBuildGradle } = require("expo/config-plugins")

const MARKER = "// pm-release-signing"

const RELEASE_SIGNING_CONFIG = `        release {
            ${MARKER}
            // PM_RELEASE_* missing: release build fails in validateSigningRelease (see CLAUDE.md)
            if (findProperty('PM_RELEASE_STORE_FILE')) {
                storeFile file(findProperty('PM_RELEASE_STORE_FILE'))
                storePassword findProperty('PM_RELEASE_STORE_PASSWORD')
                keyAlias findProperty('PM_RELEASE_KEY_ALIAS')
                keyPassword findProperty('PM_RELEASE_KEY_PASSWORD')
            }
        }
`

const withReleaseSigning = config =>
	withAppBuildGradle(config, mod => {
		const { contents } = mod.modResults
		if (contents.includes(MARKER)) {
			// Already patched. Refuse a hand-edited file that signs release with the debug key.
			if (/release \{[^}]*signingConfig signingConfigs\.debug/.test(contents)) {
				throw new Error("with-release-signing: release uses the debug signing config")
			}
			return mod
		}

		const withConfig = contents.replace(
			/(signingConfigs \{\s*debug \{[^}]*\}\n)/,
			`$1${RELEASE_SIGNING_CONFIG}`,
		)
		const withBuildType = withConfig.replace(
			/(release \{\s*\/\/ Caution![^\n]*\n\s*\/\/ see [^\n]*\n\s*)signingConfig signingConfigs\.debug/,
			"$1signingConfig signingConfigs.release",
		)

		if (withConfig === contents || withBuildType === withConfig) {
			throw new Error(
				"with-release-signing: app/build.gradle template changed, update plugins/with-release-signing.js",
			)
		}
		mod.modResults.contents = withBuildType
		return mod
	})

module.exports = withReleaseSigning
